// ==========================================================================
// UPGRADED REWORKED ECOSYSTEM SECURE FETCH ROUTER WITH MAINTENANCE CODES DETECT
// ==========================================================================
// Startup seed: /api/secure/bootstrap answers several endpoints at once.
// Each seeded answer is handed out once (profile twice) within 20 seconds,
// so the normal loaders get instant data and later refreshes stay fresh.
const _bootSeed = {};
function seedBootCache(map) {
    const exp = Date.now() + 20000;
    for (const url in map) {
        if (map[url]) {
            _bootSeed[url] = { v: map[url], exp, left: url === '/api/secure/profile' ? 2 : 1 };
        }
    }
}
async function secureFetch(url, options = {}) {
    if (!options.method || options.method === 'GET') {
        const hit = _bootSeed[url];
        if (hit && hit.left > 0 && hit.exp > Date.now()) {
            hit.left--;
            return hit.v;
        }
    }
    const absoluteUrl = url.startsWith('http') ? url : `${RENDER_URL}${url}`;
    const { timeoutMs, ...fetchOptions } = options;
    const isFormData = fetchOptions.body instanceof FormData;
    const headers = {
        ...(isFormData ? {} : { 'Content-Type': 'application/json' }),
        'X-Telegram-Init-Data': window.Telegram?.WebApp?.initData || ''
    };

    const ctrl = timeoutMs ? new AbortController() : null;
    const timer = ctrl ? setTimeout(() => ctrl.abort(), timeoutMs) : null;

    const config = {
        ...fetchOptions,
        ...(ctrl ? { signal: ctrl.signal } : {}),
        headers: {
            ...headers,
            ...fetchOptions.headers
        }
    };

    try {
        const response = await fetch(absoluteUrl, config);
        if (response.status === 403) {
            const errData = await response.json().catch(() => ({}));
            if (errData.banned) {
                const reason = errData.message || 'Your account has been suspended by an administrator.';
                showBanOverlay(reason);
                throw new Error('Account banned: ' + reason);
            }
            return { ...errData, error: errData.error || 'Access denied' };
        }

        if (!response.ok) {
            const errorPayload = await response.json().catch(() => ({}));
            return { ...errorPayload, error: errorPayload.error || `HTTP Error: ${response.status}` };
        }

        return await response.json();

    } catch (networkException) {
        console.error(`[Gateway Network Fault] Path: ${absoluteUrl} Trace:`, networkException.message);
        throw networkException;
    } finally {
        if (timer) clearTimeout(timer);
    }
}
// Wait (max 4 s) until every stylesheet has loaded, so the app is never shown unstyled.
function waitForStyles() {
    var t0 = performance.now();
    return Promise.race([
        window.__cssReady || Promise.resolve(),
        new Promise(function (r) { setTimeout(r, 2000); })
    ]).then(function () {
        window.__css = { waited: Math.round(performance.now() - t0), at: Math.round(performance.now()) };
    });
}
// ---- Instant open for returning users (last balance kept on this phone) ----
function readSavedProfile() {
    try {
        const uid = window.Telegram?.WebApp?.initDataUnsafe?.user?.id;
        const raw = JSON.parse(localStorage.getItem('dash_saved_profile') || 'null');
        return (raw && uid && raw.uid === uid && !raw.is_banned) ? raw : null;
