}
async function initApp() {
    try {
        if (window.__NOT_TMA) return;
        setLoadingProgress(50, 'Connecting...');
        cachedUserProfile = null;

        const user = window.Telegram?.WebApp?.initDataUnsafe?.user || {
            first_name: "Gamer",
            username: "User",
            id: 0,
            photo_url: ""
        };

        const userNameEl = document.getElementById('user-name');
        if (userNameEl) {
            userNameEl.innerText = user.first_name || user.username || "User";
        }

        const headerImg = document.getElementById('header-avatar');
        const headerFallback = document.getElementById('header-avatar-fallback');
        if (headerImg && headerFallback) {
            if (user.photo_url) {
                headerImg.src = user.photo_url;
                headerImg.classList.remove('hidden');
                headerFallback.classList.add('hidden');
            } else {
                headerImg.classList.add('hidden');
                headerFallback.classList.remove('hidden');
                headerFallback.innerText = user.first_name ? user.first_name.charAt(0).toUpperCase() : "E";
            }
        }

        // Returning user: open the app now using the last saved balance,
        // while fresh data loads behind it. First-time users keep the loading screen.
        const saved = readSavedProfile();
        if (saved) {
            try {
                const balanceMain = document.getElementById('balance-main');
                if (balanceMain) balanceMain.innerText = parseInt(saved.balance || 0).toLocaleString();
                updateHeaderBalances(saved.balance);
                renderBannerSkeleton();
                await waitForStyles();                      
                setLoadingProgress(100, 'Ready!');
                hideLoadingScreen();
            } catch (e) { /* fall back to the normal path */ }
        }

        // One request for startup data. If it fails, every loader uses its own call.
        const boot = (window.__bootPromise && await window.__bootPromise)
            || await secureFetch('/api/secure/bootstrap').catch(() => null);

        if (boot && boot.success) {
            seedBootCache({
                '/api/admin/check': boot.admin,
                '/api/secure/profile': boot.profile,
                '/api/secure/tasks-with-progress': boot.tasks,
                '/api/secure/referrals': boot.referrals,
                '/api/banners': boot.banners,
                '/api/settings': boot.settings
            });
        }
        const profilePromise = secureFetch('/api/secure/profile').catch(() => null);
        await fetchAdminStatus();

        setLoadingProgress(55, 'Verifying account...');
        if (isCurrentUserAdmin) {
            document.getElementById('admin-badge')?.classList.remove('hidden');
            document.getElementById('nav-admin')?.classList.remove('hidden');
            const alertsBtn = document.querySelector('button[onclick="switchAdminPanel(\'panel-notifications\')"]');
            if (alertsBtn) alertsBtn.classList.remove('opacity-50');
        }

        // 3. Fetch profile
        setLoadingProgress(60, 'Loading profile...');
        const data = await profilePromise;

        if (data && !data.error) {
            let activeProfile = null;
            if (typeof data.balance === 'number') {
                activeProfile = data;
            } else if (data.success && data.profile) {
                activeProfile = data.profile;
            }

            if (activeProfile) {
                if (activeProfile.is_banned) {
                    showBanOverlay('Your account has been suspended by an administrator.');
                    return;
                }

                cachedUserProfile = activeProfile;
                saveProfileForNextOpen(activeProfile);

                const balanceMainEl = document.getElementById('balance-main');
                if (balanceMainEl) balanceMainEl.innerText = parseInt(activeProfile.balance || 0).toLocaleString();

                updateHeaderBalances(activeProfile.balance);
            }
        } else {
            console.warn("Profile structure unexpected or unauthenticated:", data);
        }

        // Profile is in: show the app now, the rest loads behind it
        // (each loader draws its own skeleton)
        await waitForStyles();
        setLoadingProgress(100, 'Ready!');
        hideLoadingScreen();
        setTimeout(function () { if (window.__loadAds) window.__loadAds(); }, 500);

        Promise.allSettled([
            initBannerCarousel(),
            loadAvailableTasks(),
            loadReferralData(),
            loadUserProfileMetrics(),
            isCurrentUserAdmin ? loadAdminData() : Promise.resolve(),
        ]).then(results => {
            results.forEach(r => {
                if (r.status === 'rejected') console.warn('Background load failed:', r.reason);
            });
        });

    } catch (err) {
        console.error("Initialization pipeline caught an execution error:", err.message);
        } finally {
        hideLoadingScreen();
        checkStreakOnAppStart();
        handleDeepLinkSection();
    }

}
