   FAST TASK WIDGET - AdsGram task widget, 3 claims/day
   ============================================================ */
let _fastTaskConfigCache = null;
let _fastTaskRefreshCooldown = false;
let _fastTaskNextAvailableAt = 0; // timestamp; 0 = no cooldown active
let _fastTaskCountdownInterval = null;


function refreshFastTaskWidget() {
    if (_fastTaskRefreshCooldown) return;
    _fastTaskRefreshCooldown = true;

    const btn = document.getElementById('fast-task-refresh-btn');
    let secondsLeft = 5;

    if (btn) {
        btn.disabled = true;
        btn.classList.add('opacity-40');
        btn.innerText = secondsLeft;
    }

    loadAndShowAdsgram();

    const countdown = setInterval(() => {
        secondsLeft--;
        if (btn && secondsLeft > 0) {
            btn.innerText = secondsLeft;
        } else {
            clearInterval(countdown);
            _fastTaskRefreshCooldown = false;
            if (btn) {
                btn.disabled = false;
                btn.classList.remove('opacity-40');
                btn.innerText = '🔄';
            }
        }
    }, 1000);
}

// Shows a live "next task in MM:SS" countdown in place of the widget, and
// automatically loads the next task once it hits zero.
function showFastTaskCooldown(container, remainingLabel) {
    if (_fastTaskCountdownInterval) clearInterval(_fastTaskCountdownInterval);

    const render = () => {
        const msLeft = _fastTaskNextAvailableAt - Date.now();
        if (msLeft <= 0) {
            clearInterval(_fastTaskCountdownInterval);
            _fastTaskCountdownInterval = null;
            _fastTaskNextAvailableAt = 0;
            loadAndShowAdsgram();
            return;
        }
        const totalSeconds = Math.ceil(msLeft / 1000);
        const mm = Math.floor(totalSeconds / 60);
        const ss = String(totalSeconds % 60).padStart(2, '0');
        container.innerHTML = `
                    <div class="flex items-center justify-center py-3">
                      <div class="bg-yellow-500/10 border border-yellow-500/20 rounded-full px-4 py-1.5 flex items-center space-x-2">
                          <span class="animate-pulse text-yellow-400 text-xs">⏳</span>
                          <span class="text-yellow-300 text-[11px] font-medium tracking-wide">Ready in ${mm}:${ss}</span>
                      </div>
                   </div>
                              `;
        if (remainingLabel && _fastTaskConfigCache) {
            remainingLabel.innerText = `${_fastTaskConfigCache.claimsRemainingToday}/${_fastTaskConfigCache.dailyLimit} left · +${_fastTaskConfigCache.reward} each`;
        }
    };

    render();
    _fastTaskCountdownInterval = setInterval(render, 1000);
}

async function loadAndShowAdsgram() {
    const container = document.getElementById('fast-task-widget-container');
    const remainingLabel = document.getElementById('fast-task-remaining');
    if (!container) return;


    if (_fastTaskNextAvailableAt > Date.now()) {
        showFastTaskCooldown(container, remainingLabel);
        return;
    }

    container.innerHTML = '<p class="text-center text-[10px] text-slate-500 py-3">Loading...</p>';

    try {
        const cfg = await secureFetch('/api/secure/fast-task-config');

        if (!cfg || !cfg.success) {
            container.innerHTML = '<p class="text-center text-[10px] text-red-400 py-3">Failed to load Fast Task.</p>';
            return;
        }

        _fastTaskConfigCache = cfg;

        if (!cfg.enabled || !cfg.blockId) {
            if (remainingLabel) remainingLabel.innerText = '';
            container.innerHTML = getEmptyStateHTML('⏳', 'Not available', 'Not available right now.');
            return;
        }

        if (remainingLabel) {
            remainingLabel.innerText = `${cfg.claimsRemainingToday}/${cfg.dailyLimit} left · +${cfg.reward} each`;
        }

        if (cfg.claimsRemainingToday <= 0) {
            container.innerHTML = getEmptyStateHTML('✅', 'Daily limit reached', 'Come back tomorrow!');
            return;
        }

        // Mount widget
        container.innerHTML = '';
        const widget = document.createElement('adsgram-task');
        widget.setAttribute('data-block-id', cfg.blockId);

        const rewardSlot = document.createElement('span');
        rewardSlot.setAttribute('slot', 'reward');
        rewardSlot.className = 'fast-task-slot-reward';
        rewardSlot.textContent = `+${cfg.reward} DASH`;

        const buttonSlot = document.createElement('button');
        buttonSlot.setAttribute('slot', 'button');
        buttonSlot.className = 'fast-task-slot-btn';
        buttonSlot.textContent = 'Complete';

        const claimSlot = document.createElement('button');
        claimSlot.setAttribute('slot', 'claim');
        claimSlot.className = 'fast-task-slot-btn fast-task-slot-claim';
        claimSlot.textContent = 'Claim';

        const doneSlot = document.createElement('span');
        doneSlot.setAttribute('slot', 'done');
        doneSlot.className = 'fast-task-slot-done';
        doneSlot.textContent = '✅ Done';

        widget.append(rewardSlot, buttonSlot, claimSlot, doneSlot);

        widget.addEventListener('reward', onFastTaskReward);
        widget.addEventListener('onBannerNotFound', () => {
         container.innerHTML = getEmptyStateHTML('📭', 'No tasks available', 'Come back later.');
        });
        widget.addEventListener('onError', (e) => {
         console.error('AdsGram task widget error:', e);
         container.innerHTML = getErrorStateHTML('⚠️', 'Ad failed to load', 'Try refreshing.');
        });
        widget.addEventListener('onTooLongSession', () => {
            container.innerHTML = getErrorStateHTML('⏰', 'Session expired', 'Please reopen the Tab.');
        });
        container.appendChild(widget);

    } catch (e) {
    console.error('Ads list error:', e);
    const offline = navigator.onLine === false;
    container.innerHTML = offline
        ? getErrorStateHTML('📡', 'No connection', 'Check your internet and try again.')
        : getErrorStateHTML('🛰️', 'Server unreachable', 'Please try again.');
}
}

// Fires when the AdsGram task widget confirms the user completed the task.
let _fastTaskClaimInFlight = false;
const FAST_TASK_COOLDOWN_MS = 3 * 60 * 1000; // 3 minutes between claims

async function onFastTaskReward() {
    console.log("AdsGram fired reward! Is lock active?", _fastTaskClaimInFlight);

    if (_fastTaskClaimInFlight) return;
    _fastTaskClaimInFlight = true;

    try {
         let res = await secureFetch('/api/secure/fast-task-claim', { method: 'POST' });

        // AdsGram's server confirmation can land a moment after the widget event
        for (let i = 0; i < 6 && !res.success && /not confirmed/i.test(res.error || ''); i++) {
            await new Promise(r => setTimeout(r, 1500));
            res = await secureFetch('/api/secure/fast-task-claim', { method: 'POST' });
        }
        if (res.success) {
            tg.HapticFeedback.notificationOccurred('success');
            showNotificationToast(`🎯 Fast Task Claimed! +${res.reward} DASH added.`, 'success');
            updateHeaderBalances(res.newBalance);
            if (_fastTaskConfigCache) _fastTaskConfigCache.claimsRemainingToday = res.claimsRemainingToday;

            _fastTaskNextAvailableAt = Date.now() + FAST_TASK_COOLDOWN_MS;
        } else {
            showNotificationToast(res.error || 'Could not record reward', 'error');
        }
    } catch (err) {
        console.error('Fast task claim error:', err);
        showNotificationToast('Network error claiming reward', 'error');
    } finally {
        _fastTaskClaimInFlight = false;
        loadAndShowAdsgram();
    }
}

