function parsePrizeList(str) {
    const arr = String(str || '').split(',')
        .map(s => parseFloat(s.trim()))
        .filter(n => !isNaN(n) && n >= 0)
        .slice(0, 5);
    while (arr.length < 5) arr.push(0);
    return arr;
}

